import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 미리보기 가능 확장자 (HWP·Word·Excel·PPT)
const PREVIEW_EXTENSIONS = ['hwp', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx'];

// 가정: 임직원 권한이 있으면 다운로드를 허용한다. 세부 제한은 통합 권한관리(공통)가 맡는다.
const DOWNLOAD_ALLOWED = true;

@Controller('api/v1')
export class FnSfr03105Controller {
  @Get('/attachments')
  async listAttachments(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const q = checks.queryOf(req.query);
    const targetType = typeof q['targetType'] === 'string' ? String(q['targetType']).trim() : '';
    const targetIdText = String(q['targetId'] ?? '').trim();
    const targetId = Number(targetIdText);
    if (!targetType || !targetIdText || !Number.isInteger(targetId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '업무 대상 유형과 업무 대상 ID를 정확히 입력해 주세요.');
    }
    const page = q['page'] === undefined || q['page'] === '' ? 0 : Number(q['page']);
    const sizeRaw = q['size'] === undefined || q['size'] === '' ? 20 : Number(q['size']);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기가 올바르지 않습니다.');
    }
    const size = Math.min(sizeRaw, 200);
    return transaction(async (db) => {
      const params = {
        targetType,
        targetId,
        size,
        offset: page * size,
      };
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM attachment WHERE target_type = :targetType AND target_id = CAST(:targetId AS bigint)',
        { targetType, targetId },
      );
      const rows = await db.query(
        'SELECT attachment_id AS "attachmentId", file_name AS "fileName", file_extension AS "fileExtension", file_size AS "fileSize" ' +
          'FROM attachment WHERE target_type = :targetType AND target_id = CAST(:targetId AS bigint) ' +
          'ORDER BY attachment_id DESC LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)',
        params,
      );
      const items = rows.map((row: any) => {
        const ext = String(row.fileExtension ?? '').toLowerCase().replace('.', '');
        return {
          attachmentId: Number(row.attachmentId),
          fileName: row.fileName,
          fileExtension: row.fileExtension,
          fileSize: row.fileSize === null || row.fileSize === undefined ? null : Number(row.fileSize),
          downloadAllowed: DOWNLOAD_ALLOWED,
          previewAvailable: PREVIEW_EXTENSIONS.includes(ext),
        };
      });
      return { items, page, size, total: Number((counts[0] as any)?.total ?? 0) };
    });
  }

  @Get('/attachments/:attachmentId/download')
  async downloadAttachment(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const attachmentId = req.params['attachmentId'];
    if (!/^\d+$/.test(attachmentId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '첨부파일 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT attachment_id AS "attachmentId", file_name AS "fileName", ecm_ref AS "ecmRef" FROM attachment WHERE attachment_id = CAST(:attachmentId AS bigint)',
        { attachmentId },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'ATTACHMENT_NOT_FOUND', '첨부파일을 찾을 수 없습니다.');
      }
      if (!DOWNLOAD_ALLOWED) {
        throw new ApiError(422, 'DOWNLOAD_NOT_ALLOWED', '다운로드 권한이 없습니다. 미리보기만 이용할 수 있습니다.');
      }
      const row = rows[0] as any;
      if (!row.ecmRef) {
        throw new ApiError(502, 'ECM_LINK_FAILED', 'ECM 연계 조회에 실패했습니다. 잠시 후 다시 시도해 주세요.');
      }
      // 가정: 이 모듈에는 ECM 클라이언트가 없어 ECM 저장 참조를 파일 내용 자리로 돌려준다.
      return { file: String(row.ecmRef) };
    });
  }
}

