import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  TextInput,
  NumberInput,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

export default function FnSfr03105Page({ role, notify }: PageProps) {
  const [targetType, setTargetType] = useState('');
  const [targetId, setTargetId] = useState<number | string>('');
  const [applied, setApplied] = useState<{ targetType: string; targetId: number | string } | null>(null);
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);
  const [fileText, setFileText] = useState('');
  const [newType, setNewType] = useState('');
  const [newId, setNewId] = useState<number | string>('');
  const [downloaded, setDownloaded] = useState('');
  const [preview, setPreview] = useState('');
  const [actionError, setActionError] = useState('');

  const { data, error, reload } = useData<Page | null>(async () => {
    if (!applied) return null;
    return call<Page>('GET', '/attachments', role, undefined, {
      targetType: applied.targetType,
      targetId: applied.targetId,
      page,
      size: 20,
    });
  }, [applied, page, role]);

  function search() {
    if (!targetType.trim() || targetId === '') {
      notify('업무 대상 유형과 업무 대상 ID를 입력해 주세요.');
      return;
    }
    setPage(0);
    setApplied({ targetType: targetType.trim(), targetId });
  }

  function reset() {
    setTargetType('');
    setTargetId('');
    setApplied(null);
    setPage(0);
  }

  function open(row: Row) {
    setSelected(row);
    setDownloaded('');
    setPreview('');
    setActionError('');
  }

  async function download(row: Row) {
    setActionError('');
    setDownloaded('');
    try {
      const res = await call<Row>('GET', `/attachments/${row.attachmentId}/download`, role);
      setDownloaded(String(res.file ?? ''));
      notify('파일을 가져왔습니다.');
    } catch (e) {
      setActionError(e instanceof Error ? e.message : '다운로드에 실패했습니다.');
    }
  }

  async function showPreview(row: Row) {
    setActionError('');
    setPreview('');
    try {
      const res = await call<Row>('GET', `/attachments/${row.attachmentId}/preview`, role);
      setPreview(String(res.previewContent ?? ''));
    } catch (e) {
      setActionError(e instanceof Error ? e.message : '미리보기를 불러오지 못했습니다.');
    }
  }

  async function create() {
    if (!fileText.trim()) {
      throw new Error('업로드 파일을 입력해 주세요.');
    }
    const body: Row = { file: fileText };
    if (newType.trim()) body.targetType = newType.trim();
    if (newId !== '') body.targetId = newId;
    await call('POST', '/attachments', role, body);
    notify('첨부파일을 등록했습니다.');
    setCreating(false);
    setFileText('');
    setNewType('');
    setNewId('');
    reload();
  }

  if (selected) {
    return (
      <div className="doc">
        <button className="ghost" onClick={() => setSelected(null)}>목록으로 돌아가기</button>
        <section className="box">
          <h2>첨부파일 정보</h2>
          <Pairs
            items={[
              ['첨부파일 ID', String(selected.attachmentId)],
              ['파일명', String(selected.fileName ?? '')],
              ['확장자', String(selected.fileExtension ?? '')],
              ['파일 크기(바이트)', <Num value={selected.fileSize} />],
              ['다운로드 허용', <Badge value={selected.downloadAllowed ? '허용' : '차단'} />],
              ['미리보기 가능', <Badge value={selected.previewAvailable ? '가능' : '불가'} />],
            ]}
          />
        </section>
        <section className="box">
          <h2>열람</h2>
          {selected.downloadAllowed ? (
            <button onClick={() => download(selected)}>다운로드</button>
          ) : (
            <p>다운로드 권한이 없어 미리보기만 이용할 수 있습니다.</p>
          )}
          {selected.previewAvailable ? (
            <button className="ghost" onClick={() => showPreview(selected)}>미리보기</button>
          ) : null}
          {actionError ? <ErrorText text={actionError} /> : null}
          {downloaded ? <p>{downloaded}</p> : null}
          {preview ? <pre>{preview}</pre> : null}
        </section>
      </div>
    );
  }

  return (
    <div className="doc">
      <h1>첨부파일 관리</h1>
      <Filters onSearch={search} onReset={reset}>
        <Field label="업무 대상 유형" required>
          <TextInput value={targetType} onChange={setTargetType} />
        </Field>
        <Field label="업무 대상 ID" required>
          <NumberInput value={targetId} onChange={setTargetId} />
        </Field>
      </Filters>
      <Band total={data?.total}>
        <button onClick={() => setCreating(true)}>첨부파일 등록</button>
      </Band>
      {error ? <ErrorText text={error} /> : null}
      <DataTable
        columns={[
          { key: 'fileName', label: '파일명' },
          { key: 'fileExtension', label: '확장자' },
          { key: 'fileSize', label: '파일 크기(바이트)', render: (r) => <Num value={r.fileSize} /> },
          { key: 'downloadAllowed', label: '다운로드', render: (r) => <Badge value={r.downloadAllowed ? '허용' : '차단'} /> },
          { key: 'previewAvailable', label: '미리보기', render: (r) => <Badge value={r.previewAvailable ? '가능' : '불가'} /> },
        ]}
        rows={data?.items ?? []}
        onRowClick={open}
        empty={applied ? '이 문서에 첨부된 파일이 없습니다. 첨부파일 등록 버튼으로 파일을 추가해 주세요.' : '업무 대상 유형과 ID를 입력하고 조회해 주세요.'}
      />
      {data ? <Pager page={data.page} size={data.size} total={data.total} onPage={setPage} /> : null}
      {creating ? (
        <Drawer title="첨부파일 등록" onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit="등록">
            <Field label="업로드 파일" required wide>
              <TextInput value={fileText} onChange={setFileText} multiline />
            </Field>
            <Field label="업무 대상 유형">
              <TextInput value={newType} onChange={setNewType} />
            </Field>
            <Field label="업무 대상 ID">
              <NumberInput value={newId} onChange={setNewId} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
